// AI: This file was generated with AI assistance. See AI-DISCLOSURE.md and ai/chats/.
import express from "express";

// AI: Bounded configuration parsing keeps retry and timeout behavior explicit and safe to simulate.
const readBoundedInteger = (name, defaultValue, minimum, maximum) => {
  const rawValue = process.env[name];

  if (rawValue === undefined) {
    return defaultValue;
  }

  if (!/^\d+$/.test(rawValue)) {
    throw new Error(
      `${name} must be an integer from ${minimum} through ${maximum}`,
    );
  }

  const value = Number(rawValue);

  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new Error(
      `${name} must be an integer from ${minimum} through ${maximum}`,
    );
  }

  return value;
};

const app = express();
const port = readBoundedInteger("PORT", 3000, 1, 65535);
const upstreamUrl = (
  process.env.UPSTREAM_URL ?? "http://incident-service:3000"
).replace(/\/$/, "");
const upstreamTimeoutMs = readBoundedInteger(
  "UPSTREAM_TIMEOUT_MS",
  2000,
  50,
  60000,
);
const maxRetries = readBoundedInteger("MAX_RETRIES", 2, 0, 5);
const safeRetryMethods = new Set(["GET", "HEAD", "OPTIONS"]);
const ignoredRequestHeaders = new Set([
  "connection",
  "content-length",
  "host",
  "transfer-encoding",
]);

const sleep = (milliseconds) =>
  new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });

const logProxyAttempt = (fields) => {
  console.log(
    JSON.stringify({
      level: "info",
      service: "incident-ambassador",
      message: "Incident proxy attempt",
      ...fields,
    }),
  );
};

const createUpstreamHeaders = (request) => {
  const headers = new Headers();

  Object.entries(request.headers).forEach(([name, value]) => {
    if (ignoredRequestHeaders.has(name) || value === undefined) {
      return;
    }

    if (Array.isArray(value)) {
      value.forEach((item) => headers.append(name, item));
      return;
    }

    headers.set(name, value);
  });

  return headers;
};

const copyResponseHeaders = (upstreamResponse, response) => {
  ["content-type", "location"].forEach((name) => {
    const value = upstreamResponse.headers.get(name);

    if (value !== null) {
      response.set(name, value);
    }
  });
};

// AI: The proxy forwards every incident route, retries only safe methods, applies per-attempt timeouts, and logs every outcome.
const proxyRequest = async (request, response) => {
  const targetUrl = new URL(request.originalUrl, `${upstreamUrl}/`);
  const mayRetry = safeRetryMethods.has(request.method);
  const maximumAttempts = mayRetry ? maxRetries + 1 : 1;
  const requestBody =
    request.method === "GET" || request.method === "HEAD"
      ? undefined
      : request.body;
  let lastStatusCode = 502;
  let lastErrorMessage = "Incident service request failed";

  for (let attempt = 1; attempt <= maximumAttempts; attempt += 1) {
    const attemptStartedAt = Date.now();
    const controller = new AbortController();
    const timeoutHandle = setTimeout(() => {
      controller.abort();
    }, upstreamTimeoutMs);

    try {
      const upstreamResponse = await fetch(targetUrl, {
        method: request.method,
        headers: createUpstreamHeaders(request),
        body: requestBody,
        signal: controller.signal,
      });
      const responseBody = Buffer.from(await upstreamResponse.arrayBuffer());
      const durationMs = Date.now() - attemptStartedAt;

      logProxyAttempt({
        method: request.method,
        path: request.originalUrl,
        attempt,
        upstreamStatus: upstreamResponse.status,
        durationMs,
        retryable: mayRetry,
      });

      if (upstreamResponse.status >= 500 && attempt < maximumAttempts) {
        lastStatusCode = upstreamResponse.status;
        lastErrorMessage = `Incident service returned ${upstreamResponse.status}`;
        await sleep(50 * attempt);
        continue;
      }

      copyResponseHeaders(upstreamResponse, response);
      response.status(upstreamResponse.status).send(responseBody);
      return;
    } catch (error) {
      const timedOut = error?.name === "AbortError";
      const durationMs = Date.now() - attemptStartedAt;

      lastStatusCode = timedOut ? 504 : 502;
      lastErrorMessage = timedOut
        ? "Incident service request timed out"
        : error instanceof Error
          ? error.message
          : String(error);

      logProxyAttempt({
        method: request.method,
        path: request.originalUrl,
        attempt,
        upstreamStatus: null,
        durationMs,
        retryable: mayRetry,
        error: lastErrorMessage,
      });

      if (attempt < maximumAttempts) {
        await sleep(50 * attempt);
        continue;
      }
    } finally {
      clearTimeout(timeoutHandle);
    }
  }

  response.status(lastStatusCode).json({
    error: {
      code: lastStatusCode === 504 ? "UPSTREAM_TIMEOUT" : "UPSTREAM_UNAVAILABLE",
      message: lastErrorMessage,
    },
  });
